import {PRODUCTS,MARKETS} from './data.mjs';
import {analyze,money,localPrice} from './engine.mjs';
import {executeSearch,filterReasons,evaluateCases,summarizeFunnel,STRATEGIES,REASONS,DEFAULT_WEIGHTS} from './search.mjs';
import {EVAL_CASES as ALL_CASES,DEV_CASES as EVAL_CASES,HOLDOUT_CASES,EVAL_VERSION} from './eval-data.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=x=>x===null?'—':(x*100).toFixed(1)+'%';
const num=x=>x===null?'—':x.toFixed(3);
const names={relevance:'需求相关性',budget:'预算适配',availability:'库存充足度',delivery:'配送时效',rating:'商品评分'};
const channelNames={keyword:'关键词',category:'品类',attribute:'属性标签',brand:'指定品牌',browse:'泛需求兜底'};
export function initialLab(){return {text:EVAL_CASES[0].text,market:'US',strategy:'match',weights:{...DEFAULT_WEIGHTS},tab:'pipeline'};}
function snapshotActive(lab){return lab.snapshot&&lab.snapshot.text===lab.text&&lab.snapshot.market===lab.market;}
function labQuery(lab){return snapshotActive(lab)?lab.snapshot.query:analyze(lab.text,lab.market);}
export function getLabResults(lab){return executeSearch(labQuery(lab),PRODUCTS,{strategy:lab.strategy,weights:lab.weights,sort:snapshotActive(lab)?lab.snapshot.sort:'match'});}
function metric(label,value,note){return `<div class="lab-metric"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`;}
function resultList(r,base=[]){return r.items.map((p,i)=>{const previous=base.findIndex(x=>x.id===p.id),delta=previous<0?'新进Top3':previous-i===0?'位置不变':previous-i>0?'↑ '+(previous-i):'↓ '+(i-previous);return `<div class="rank-item"><b>${i+1}</b><div><strong>${esc(p.name)}</strong><small>${esc(p.brand)} · ${money(localPrice(p,r.query.market),r.query.market)} · 评分 ${p.rating}</small><span>${base.length?delta+' · ':''}排序分 ${p.score.toFixed(1)}${p.diversityPenalty?' · 同品牌惩罚 −'+p.diversityPenalty:''}</span></div></div>`;}).join('')||'<div class="lab-empty">当前无符合全部硬约束的商品。</div>';}
function scoreTable(r){return `<div class="lab-scroll"><table class="lab-table"><thead><tr><th>商品 / 排名</th>${Object.entries(names).map(([k,v])=>`<th>${v}<small>权重 ${(r.weights[k]*100).toFixed(0)}%</small></th>`).join('')}<th>排序分</th><th>重排选择分</th></tr></thead><tbody>${r.final.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>初排 #${p.initialRank} → 最终 #${p.finalRank}</small></td>${Object.keys(names).map(k=>`<td>${(p.components[k]*100).toFixed(1)}<div class="mini-bar"><i style="width:${p.features[k]*100}%"></i></div></td>`).join('')}<td>${p.score.toFixed(1)}</td><td>${p.selectionScore.toFixed(1)}${p.diversityPenalty?`<small>品牌惩罚 −${p.diversityPenalty}</small>`:''}</td></tr>`).join('')||'<tr><td colspan="8">没有可排序的候选商品。</td></tr>'}</tbody></table></div>`;}
function pipeline(r){const q=r.query,p=q.preprocessing;
 return `<div class="lab-flow">${[['01','商品池',r.counts.catalog],['02','去重召回',r.counts.recalled],['03','硬过滤后',r.counts.eligible],['04','最终展示',r.counts.returned]].map(([n,k,v])=>`<div><span>${n} ${k}</span><strong>${v}<small>款</small></strong></div>`).join('')}</div>
 <div class="lab-two"><section class="panel lab-panel"><div class="lab-section-title"><span>01 / QUERY</span><h2>把一句话，变成检索条件</h2></div><dl class="query-facts"><dt>标准化输入</dt><dd>${esc(p.normalized)}</dd><dt>检索表达</dt><dd>${esc(p.rewritten)}</dd><dt>归一处理</dt><dd>${p.changes.length?esc(p.changes.join(' / ')):'无需纠错或别名替换'}</dd><dt>硬性约束</dt><dd>${esc([q.market,q.category,q.subcategory,q.brand,q.budget!=null?q.budget+' '+q.currency:'未限制预算',...(q.requiredFeatures||[])].filter(Boolean).join(' · '))}</dd><dt>软性偏好</dt><dd>${esc(q.concerns.filter(x=>!q.requiredFeatures.includes(x)).join(' · ')||'未指定')}</dd></dl><p class="lab-note">有限规则支持耳麦、蓝牙喇叭、ANC、headphons等表达归一；不宣称通用语义检索。</p></section>
 <section class="panel lab-panel"><div class="lab-section-title"><span>02 / RECALL</span><h2>多路匹配，合并去重</h2></div>${Object.entries(r.channels).map(([k,ids])=>`<div class="channel-row"><span>${channelNames[k]}</span><div class="channel-track"><i style="width:${ids.length/PRODUCTS.length*100}%"></i></div><b>${ids.length}</b></div>`).join('')}<p class="lab-note">各路按商品ID合并，命中数可重叠。当前在${PRODUCTS.length}款合成商品中直接匹配；未接入倒排索引或向量库。</p></section></div>
 <section class="panel lab-panel"><div class="lab-section-title"><span>03 / FILTER</span><h2>哪些商品被拦下，为什么？</h2><p>过滤与排序分开。再高的评分也不能突破预算、市场、库存和必要特性。</p></div><div class="lab-scroll"><table class="lab-table"><thead><tr><th>商品</th><th>召回来源</th><th>检索状态</th><th>全部过滤原因</th></tr></thead><tbody>${r.audit.map(a=>`<tr><td>${esc(a.name)}</td><td>${a.channels.map(c=>channelNames[c]).join(' / ')||'—'}</td><td><span class="status-pill ${a.recalled&&!a.reasons.length?'good':''}">${!a.recalled?'未召回':a.reasons.length?'已过滤':'进入排序'}</span></td><td>${a.recalled?(a.reasons.map(c=>REASONS[c]).join(' · ')||'满足硬约束'):'未进入候选集'}</td></tr>`).join('')}</tbody></table></div></section>
 <section class="panel lab-panel"><div class="lab-section-title"><span>04 / RANK & RE-RANK</span><h2>排名由哪些因素组成？</h2><p>每列为该因素贡献的分数，相加得到排序分。品牌多样性重排按已选同品牌数量，每次扣12分后选取下一款。</p></div>${scoreTable(r)}<p class="lab-note">权重自动归一为100%。排序分为演示规则分，不是pCTR、pCVR或购买概率；重排选择分反映选取该商品当时的品牌惩罚。</p></section>`;
}
function comparison(lab){const q=labQuery(lab),runs=Object.keys(STRATEGIES).map(strategy=>executeSearch(q,PRODUCTS,{strategy,weights:lab.weights,sort:snapshotActive(lab)?lab.snapshot.sort:'match'})),base=runs[0].items;
 return `<div class="lab-callout"><strong>策略假设</strong><p>当评分优先的结果没有充分覆盖用户用途时，加入需求匹配；当Top3品牌集中时，再增加品牌打散。对照使用相同查询、商品池和硬过滤条件。</p></div><div class="strategy-columns">${runs.map(r=>`<section class="panel lab-panel"><div class="lab-section-title"><span>${r.strategy==='rating'?'BASELINE':r.strategy==='match'?'RELEVANCE':'DIVERSITY'}</span><h2>${STRATEGIES[r.strategy].name}</h2></div>${resultList(r, r.strategy==='rating'?[]:base)}<div class="strategy-facts"><span>Top3品牌数 <b>${new Set(r.items.map(p=>p.brand)).size}</b></span><span>硬约束违规 <b>${r.items.filter(p=>filterReasons(p,r.query).length).length}</b></span></div><button class="btn full ${lab.strategy===r.strategy?'primary':''}" data-lab-strategy="${r.strategy}">${lab.strategy===r.strategy?'当前分析策略':'分析这套策略'}</button></section>`).join('')}</div><section class="panel lab-panel"><h2>怎么讲清这次策略变化</h2><p class="lab-note">先说明用户需求及约束，再对照排名变化和得分贡献。品牌数增加只证明结果更多样，不能直接证明转化提升；是否满足需求，要结合下面的离线标注和真实用户反馈。</p></section>`;
}
function evaluation(lab){const runs=Object.keys(STRATEGIES).map(strategy=>({strategy,...evaluateCases(EVAL_CASES,analyze,PRODUCTS,{strategy,weights:lab.weights})})),selected=runs.find(r=>r.strategy===lab.strategy);
 return `<div class="lab-callout"><strong>离线评估 · 共${ALL_CASES.length}条，当前${EVAL_CASES.length}条开发用例</strong><p>合成目录上的合成规则标注，相关性0–3级，未列出的商品记0；不是独立人工评审或真实线上A/B。每次调整权重只运行开发集；另有${HOLDOUT_CASES.length}条保留用例，冻结策略后通过命令行验收，不参与页面调参。</p></div><section class="panel lab-panel"><div class="lab-section-title"><span>OFFLINE BENCHMARK / ${EVAL_VERSION}</span><h2>同一组需求，比较三套策略</h2></div><div class="lab-scroll"><table class="lab-table"><thead><tr><th>策略</th><th>nDCG@3</th><th>Precision@3</th><th>召回覆盖率</th><th>约束通过率</th><th>有无结果判断</th><th>平均品牌数</th></tr></thead><tbody>${runs.map(r=>`<tr class="${r.strategy===lab.strategy?'selected-row':''}"><td>${STRATEGIES[r.strategy].name}</td><td>${num(r.metrics.ndcg)}</td><td>${pct(r.metrics.precision)}</td><td>${pct(r.metrics.recall)}</td><td>${pct(r.metrics.constraintPass)}</td><td>${pct(r.metrics.emptyAccuracy)}</td><td>${r.metrics.meanBrands.toFixed(2)}</td></tr>`).join('')}</tbody></table></div><details class="lab-definitions"><summary>查看指标口径与标注限制</summary><p>nDCG@3按(2^相关性−1)/log2(排名+1)计算并除以理想排序；Precision@3固定以3为分母，少结果不会被补齐；召回覆盖率为召回阶段命中的已标注正相关商品数/全部正相关商品数。预期无结果样本不计入前三项均值，单独检验有无结果判断。约束通过率为没有违规推荐的查询占比；不展示结果不代表一定正确，还要看有无结果判断。标注只用于当前封闭商品池，样本少且由规则生成，不能据此宣称业务增量。</p></details></section><section class="panel lab-panel"><div class="lab-section-title"><span>CASE REVIEW</span><h2>${STRATEGIES[lab.strategy].name} · 逐条复盘</h2><p>点击样本，可直接回到检索链路检查原因。</p></div><div class="lab-scroll"><table class="lab-table"><thead><tr><th>查询 / 分层</th><th>Top3 / 标注等级</th><th>nDCG@3</th><th>标注依据</th></tr></thead><tbody>${selected.rows.map(c=>`<tr><td><button class="lab-case-link" data-eval-case="${c.id}">${esc(c.text)}</button><small>${c.market} · ${c.slice}</small></td><td>${c.ids.map(id=>esc(PRODUCTS.find(p=>p.id===id).name)+' <b class="grade">'+(c.grades[id]||0)+'</b>').join('<br>')||'无结果（预期'+(c.expectedEmpty?'无结果':'有结果')+'）'}</td><td>${num(c.ndcg)}</td><td>${c.note}</td></tr>`).join('')}</tbody></table></div></section><section class="panel lab-panel"><h2>下一步线上实验如何设计</h2><p class="lab-note">假设：需求匹配能提升有效选购率。对照A使用评分优先，实验B使用需求匹配；按用户稳定分桶，保持商品、价格、界面一致。主指标采用搜索到有效结账的会话比例；支付接入后再看订单CVR。护栏包括预算违规、无结果率、延迟、退货与投诉。先预注册MDE、样本量和观察窗口，检查分流比例，再分析市场、品类及新老用户分层。本项目尚未执行线上分流或显著性检验。</p></section>`;
}
function funnel(events){const f=summarizeFunnel(events),labels={search:'搜索请求',exposed:'实际商品曝光',clicked:'商品交互',cart:'成功加购',checkout:'到达结账预览'};
 return `<div class="lab-callout"><strong>只看当前浏览器实际产生的行为</strong><p>来自导购会话，策略分析页的试跑不计入。没有事件时显示0或“—”；不会填入模拟转化数据。仅保留最近1000条事件，统计为该保留窗口内的结果。</p></div><div class="lab-metrics">${metric('商品交互率',pct(f.ctr),f.clicks+'个唯一商品交互 / '+f.impressions+'个唯一曝光')}${metric('无结果率',pct(f.zeroRate),'无候选搜索 / 搜索请求')}${metric('快速返回率',pct(f.quickBackRate),'交互后10秒内关闭详情且未加购')}${metric('支付CVR / GMV','未接入','结账预览不等于真实订单')}</div><section class="panel lab-panel"><div class="lab-section-title"><span>OBSERVED FUNNEL</span><h2>从搜索，到结账预览</h2><p>按searchId去重计数，逐级关联同一次搜索。商品交互包含打开详情或开始选择颜色。</p></div>${f.stages.map((s,i)=>`<div class="funnel-row"><span>${labels[s.key]}</span><div class="funnel-track"><i style="width:${f.searches?s.count/f.searches*100:0}%"></i></div><strong>${s.count}</strong><small>${i?(f.stages[i-1].count?pct(s.count/f.stages[i-1].count):'—')+' 上一步转化':'搜索级去重'}</small></div>`).join('')}<p class="lab-note">曝光：商品卡片至少50%进入视口；同searchId、商品ID去重。当前没有停留时长阈值或反作弊。加购和结账关联购物车内保存的来源；同商品不同搜索合并购物车后，采用最后一次有效搜索来源。已截断的事件或跨设备行为无法恢复。这里的“商品交互率”不能当作平台标准CTR。</p><div class="button-row"><button class="btn primary" data-nav="assistant">去导购页产生真实操作</button><button class="btn" data-action="refresh-lab">刷新漏斗</button><button class="btn" data-action="export-events">导出原始事件</button></div></section>`;
}
export function renderStrategyPage(lab,events,activeStrategy,L){const r=getLabResults(lab);
 return `<div class="page-head"><div><div class="eyebrow">SEARCH STRATEGY STUDIO</div><h1>${L('让每一次排序，都有依据。','Every ranking has a reason.')}</h1><p>${L('从需求理解到策略验证，查看商品为什么出现、为什么排在这里。','Trace retrieval, filtering, ranking, and evaluation.')}</p></div><button class="btn" data-action="export-strategy">导出策略分析</button></div><div class="lab-purpose"><div><strong>业务问题</strong><span>用户表达模糊，单看评分难以选到符合用途的商品。</span></div><div><strong>策略目标</strong><span>先满足硬约束，再优化需求匹配与选择空间。</span></div><div><strong>当前导购策略</strong><span>${STRATEGIES[activeStrategy||'match'].name}</span></div></div><section class="panel lab-config"><form id="strategy-form"><label for="lab-query">${L('输入一条需求，检查完整检索链路','Inspect a shopping request')}</label><div class="lab-query-row"><input id="lab-query" name="query" value="${esc(lab.text)}" maxlength="1000" required><select id="lab-market" aria-label="分析市场">${Object.entries(MARKETS).map(([k,m])=>`<option value="${k}" ${lab.market===k?'selected':''}>${m.flag} ${k} · ${m.currency}</option>`).join('')}</select><button class="btn primary" type="submit">运行分析 ${'↗'}</button></div></form>${snapshotActive(lab)?'<p class="lab-note">来自导购对话的条件快照，保留继承预算和偏好；本轮排序：'+esc(lab.snapshot.sort)+'。修改查询后重新独立分析。</p>':''}<div class="lab-presets">${EVAL_CASES.filter(c=>['q13','q17','q21','q25','q29','q33','q37'].includes(c.id)).map(c=>`<button data-eval-case="${c.id}">${c.slice}</button>`).join('')}</div><div class="lab-policy-row"><label for="lab-strategy">分析策略</label><select id="lab-strategy">${Object.entries(STRATEGIES).map(([k,v])=>`<option value="${k}" ${lab.strategy===k?'selected':''}>${v.name}</option>`).join('')}</select><button class="btn small" data-action="apply-strategy">应用到导购 · 开始新对话</button><small>实验页调整不会影响购物助手，应用后才生效。</small></div><details class="weight-controls" ${lab.weightsOpen?'open':''}><summary>调整需求匹配权重 · ${Object.values(lab.weights).reduce((a,b)=>a+b,0)}份，按比例归一</summary><div class="weight-grid">${Object.entries(names).map(([k,v])=>`<label>${v}<output id="weight-value-${k}">${lab.weights[k]}</output><input type="range" min="0" max="100" step="1" value="${lab.weights[k]}" data-lab-weight="${k}" aria-label="${v}权重"></label>`).join('')}</div><p class="lab-note">权重只影响B/C分析结果；A只按商品评分排序。点击应用后会携带当前权重进入新导购对话。</p><button class="btn small" data-action="reset-weights">恢复默认权重</button></details></section><div class="lab-tabs" role="tablist" aria-label="搜索策略分析视图">${[['pipeline','链路分析','Pipeline'],['compare','策略对照','Compare'],['evaluation','离线评估','Evaluation'],['funnel','行为漏斗','Funnel'],['decision','策略决策','Decisions']].map(([k,zh,en])=>`<button role="tab" aria-selected="${lab.tab===k}" class="${lab.tab===k?'active':''}" data-lab-tab="${k}">${L(zh,en)}</button>`).join('')}</div><div class="lab-content">${lab.tab==='pipeline'?pipeline(r):lab.tab==='compare'?comparison(lab):lab.tab==='evaluation'?evaluation(lab):lab.tab==='decision'?decision(lab):funnel(events)}</div><p class="lab-boundary">规则策略演示 · ${PRODUCTS.length}款合成商品 · 非实时汇率 · 无真实交易或线上A/B增量结论</p>`;
}
function decision(lab){
 const a=evaluateCases(EVAL_CASES,analyze,PRODUCTS,{strategy:'rating'}),b=evaluateCases(EVAL_CASES,analyze,PRODUCTS,{strategy:lab.strategy,weights:lab.weights}),delta=b.metrics.ndcg-a.metrics.ndcg;
 const gaps=b.rows.filter(r=>r.ndcg!==null).map(r=>({...r,baseline:a.rows.find(x=>x.id===r.id)})).filter(r=>r.ndcg<r.baseline.ndcg-1e-9).sort((x,y)=>(x.ndcg-x.baseline.ndcg)-(y.ndcg-y.baseline.ndcg)).slice(0,3);
 const result=lab.strategy==='rating'?'当前选择的是基线策略，可切换B或C提出并检验新的假设。':delta<0?'当前样本未支持替换评分基线。先复盘退化样本并修订策略，再做独立评估。':'当前样本可支持进一步验证，尚不足以证明线上收益或直接全量上线。';
 return `<div class="lab-callout"><strong>策略产品的工作：目标 → 定位 → 假设 → 验证 → 决策</strong><p>功能变化承载策略；数据与案例决定这项策略是否值得继续。下面的结论根据当前权重与固定评估集重新计算。</p></div><div class="lab-two"><section class="panel lab-panel"><div class="lab-section-title"><span>01 / DEFINE THE PROBLEM</span><h2>目标与人群</h2></div><dl class="query-facts"><dt>业务目标</dt><dd>提高用户找到符合用途且可购买商品的效率。</dd><dt>先关注谁</dt><dd>有明确预算与用途、但没有指定型号的导购用户；先复盘耳机出行与送礼等样本分层。</dd><dt>当前信号</dt><dd>查看同一查询下的Top3相关性、硬约束通过与无结果判断，避免只用点击增加判断成功。</dd><dt>线上主指标</dt><dd>搜索到有效店铺结账的会话比例；当前只有演示预览，尚不能计算真实有效结账转化。</dd><dt>护栏</dt><dd>预算与库存违规、无结果率、延迟、退货与投诉；后两项等待真实店铺数据。</dd></dl></section><section class="panel lab-panel"><div class="lab-section-title"><span>02 / MAKE A DECISION</span><h2>证据决定下一步</h2></div><div class="lab-metrics decision-metrics">${metric('基线 nDCG@3',num(a.metrics.ndcg),'A · 评分优先')}${metric('当前策略变化',(delta>=0?'+':'')+delta.toFixed(3),STRATEGIES[lab.strategy].name)}</div><p class="decision-result">${result}</p><p class="lab-note">${EVAL_CASES.length}条合成规则标注样本只用于发现问题。不是随机流量实验，差值不具有线上因果或统计显著性含义。</p></section></div><section class="panel lab-panel"><div class="lab-section-title"><span>03 / DIAGNOSE CASES</span><h2>先看退化最大的样本</h2><p>沿用户需求 → 候选 → 过滤 → 排序逐层排查。以下差值为当前策略相对A的nDCG变化。</p></div><div class="lab-scroll"><table class="lab-table"><thead><tr><th>样本与分层</th><th>基线 / 当前</th><th>变化</th><th>下一步验证</th></tr></thead><tbody>${gaps.map(c=>`<tr><td><button class="lab-case-link" data-eval-case="${c.id}">${esc(c.text)}</button><small>${c.slice}</small></td><td>${num(c.baseline.ndcg)} / ${num(c.ndcg)}</td><td>${(c.ndcg-c.baseline.ndcg).toFixed(3)}</td><td>核对标注规则并补充独立人评；检查预算适配、配送和库存分是否挤压了用途相关性。单次案例不直接证明根因。</td></tr>`).join('')||'<tr><td colspan="4">当前样本没有退化案例，仍需独立评估验证。</td></tr>'}</tbody></table></div></section><section class="panel lab-panel"><div class="lab-section-title"><span>04 / PRIORITIZE & EXPERIMENT</span><h2>策略假设与验证计划</h2></div><div class="lab-scroll"><table class="lab-table"><thead><tr><th>优先级</th><th>假设 / 方案</th><th>如何验证</th><th>决策条件</th></tr></thead><tbody><tr><td>P0 · 可信结果</td><td>预算、可售与必要属性作为硬约束，任何排序不得越过。</td><td>边界用例、所有策略的约束检查、预期无结果样本。</td><td>发现违规先修复；未出现违规也不代表推荐足够相关。</td></tr><tr><td>P1 · 相关性</td><td>预算适配靠近预算78%的假设可能偏向某些价格带。对照降低预算权重、提高用途相关性。</td><td>保持标注不变做权重消融；再收集独立评审与新增测试集，避免在同一批样本上过拟合。</td><td>离线相关性与覆盖通过后，才进入小范围真实流量实验。</td></tr><tr><td>P2 · 选择空间</td><td>同品牌逐次惩罚可以增加选择，但可能把更符合用途的商品后移。</td><td>比较Top3品牌数与nDCG；查看用户对比、加购和最终选购反馈。</td><td>多样性提升且相关性护栏可接受，再判断是否值得实验。</td></tr></tbody></table></div><div class="experiment-brief"><strong>真实A/B计划 · 尚未执行</strong><p>按用户稳定随机分桶，A/B同时间窗、同商品价格与页面；预注册主指标、最小可检测提升MDE、样本量和观察期。先检查事件完整性、归因及样本比例，再看总体和人群分层。主指标改善、护栏稳定时逐步扩量；证据不足则继续观察或修订，护栏恶化则回滚。当前不能据离线差值估算GMV收益。</p></div></section>`;
}
export function exportStrategy(lab){return {createdAt:new Date().toISOString(),scope:'synthetic offline evaluation; no online uplift claim',evaluationVersion:EVAL_VERSION,configuration:lab,search:getLabResults(lab),evaluation:evaluateCases(EVAL_CASES,analyze,PRODUCTS,{strategy:lab.strategy,weights:lab.weights})};}
